-- Run once in a NEW Supabase project. Review before executing.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, display_name text, role text not null default 'staff' check(role in ('owner','staff')), created_at timestamptz default now());
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), name text not null, phone text, notes text, created_at timestamptz default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), name text not null, category text default 'Yogurt', price numeric(12,2) not null default 0 check(price>=0), unit_cost numeric(12,2) not null default 0 check(unit_cost>=0), active boolean not null default true, created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_no bigint generated by default as identity unique, customer_id uuid references public.customers(id) on delete set null, channel text not null default 'walk-in' check(channel in ('walk-in','preorder','delivery')), status text not null default 'pending' check(status in ('pending','preparing','ready','completed','cancelled')), fulfillment_at timestamptz, notes text, discount numeric(12,2) not null default 0 check(discount>=0), created_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, quantity numeric(12,2) not null check(quantity>0), unit_price numeric(12,2) not null check(unit_price>=0), unit_cost numeric(12,2) not null default 0 check(unit_cost>=0));
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, amount numeric(12,2) not null check(amount>0), method text not null default 'cash' check(method in ('cash','transfer','card','platform','other')), created_at timestamptz default now());
create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), category text not null default 'Other', description text not null, amount numeric(12,2) not null check(amount>=0), expense_date date not null default current_date, created_at timestamptz default now());
create table if not exists public.ingredients (id uuid primary key default gen_random_uuid(), name text not null, unit text not null default 'g', quantity numeric(14,3) not null default 0 check(quantity>=0), reorder_level numeric(14,3) not null default 0 check(reorder_level>=0), unit_cost numeric(12,4) not null default 0 check(unit_cost>=0), created_at timestamptz default now());
create table if not exists public.inventory_movements (id uuid primary key default gen_random_uuid(), ingredient_id uuid not null references public.ingredients(id) on delete cascade, delta numeric(14,3) not null check(delta<>0), reason text not null, created_at timestamptz default now());
create table if not exists public.production_batches (id uuid primary key default gen_random_uuid(), product_id uuid references public.products(id) on delete set null, batch_code text not null, produced_qty numeric(14,3) not null check(produced_qty>0), remaining_qty numeric(14,3) not null check(remaining_qty>=0), unit text not null default 'g', produced_at date not null default current_date, expires_at date, notes text, created_at timestamptz default now(), check(remaining_qty<=produced_qty));
create table if not exists public.store_settings (id integer primary key default 1 check(id=1), store_name text not null default 'Greek Yogurt Studio', currency text not null default 'THB', updated_at timestamptz default now());
insert into public.store_settings(id) values(1) on conflict do nothing;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid()) $$;
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='owner') $$;
revoke all on function public.is_staff() from public; revoke all on function public.is_owner() from public;
grant execute on function public.is_staff() to authenticated; grant execute on function public.is_owner() to authenticated;
create or replace function public.new_user_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,display_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1)),'staff'); return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user_profile();
insert into public.profiles(id,email,display_name) select id,email,coalesce(raw_user_meta_data->>'display_name',split_part(email,'@',1)) from auth.users on conflict(id) do nothing;
-- Row security: no anonymous access, and no client-side deletion of financial records.
do $$ declare t text; begin foreach t in array array['profiles','customers','products','orders','order_items','payments','expenses','ingredients','inventory_movements','production_batches','store_settings'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists staff_read on public.%I',t); execute format('create policy staff_read on public.%I for select to authenticated using (public.is_staff())',t); end loop; end $$;
-- Profiles: owner may manage staff roles. Staff may edit their own display name only through a dedicated RPC (below).
create policy owner_insert_profiles on public.profiles for insert to authenticated with check(public.is_owner());
create policy owner_update_profiles on public.profiles for update to authenticated using(public.is_owner()) with check(public.is_owner());
create policy owner_delete_profiles on public.profiles for delete to authenticated using(public.is_owner());
do $$ declare t text; begin foreach t in array array['customers','products','orders','order_items','payments','expenses','ingredients','inventory_movements','production_batches','store_settings'] loop execute format('drop policy if exists staff_insert on public.%I',t); execute format('create policy staff_insert on public.%I for insert to authenticated with check(public.is_staff())',t); execute format('drop policy if exists staff_update on public.%I',t); execute format('create policy staff_update on public.%I for update to authenticated using(public.is_staff()) with check(public.is_staff())',t); end loop; end $$;
-- Delete only permitted for owner, to limit accidental loss.
do $$ declare t text; begin foreach t in array array['customers','products','orders','order_items','payments','expenses','ingredients','inventory_movements','production_batches'] loop execute format('drop policy if exists owner_delete on public.%I',t); execute format('create policy owner_delete on public.%I for delete to authenticated using(public.is_owner())',t); end loop; end $$;
-- Atomically adjust ingredient stock; logs each adjustment and prevents negative balances.
create or replace function public.adjust_inventory(p_ingredient_id uuid,p_delta numeric,p_reason text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_staff() then raise exception 'Not authorized'; end if; if p_delta=0 or trim(coalesce(p_reason,''))='' then raise exception 'Provide a nonzero change and reason'; end if; update public.ingredients set quantity=quantity+p_delta where id=p_ingredient_id and quantity+p_delta>=0; if not found then raise exception 'Ingredient missing or insufficient stock'; end if; insert into public.inventory_movements(ingredient_id,delta,reason) values(p_ingredient_id,p_delta,p_reason); end $$;
revoke all on function public.adjust_inventory(uuid,numeric,text) from public;
grant execute on function public.adjust_inventory(uuid,numeric,text) to authenticated;
-- Prevent direct client changes to inventory quantity; changes must use adjust_inventory RPC.
create or replace function public.guard_ingredient_quantity() returns trigger language plpgsql as $$ begin if new.quantity is distinct from old.quantity and current_setting('app.inventory_rpc',true) is distinct from 'yes' then raise exception 'Use adjust_inventory to change quantity'; end if; return new; end $$;
-- RPC sets local flag for protected update.
create or replace function public.adjust_inventory(p_ingredient_id uuid,p_delta numeric,p_reason text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_staff() then raise exception 'Not authorized'; end if; if p_delta=0 or trim(coalesce(p_reason,''))='' then raise exception 'Provide a nonzero change and reason'; end if; perform set_config('app.inventory_rpc','yes',true); update public.ingredients set quantity=quantity+p_delta where id=p_ingredient_id and quantity+p_delta>=0; if not found then raise exception 'Ingredient missing or insufficient stock'; end if; insert into public.inventory_movements(ingredient_id,delta,reason) values(p_ingredient_id,p_delta,p_reason); end $$;
drop trigger if exists protect_ingredient_quantity on public.ingredients;
create trigger protect_ingredient_quantity before update on public.ingredients for each row execute function public.guard_ingredient_quantity();
create index if not exists idx_orders_created on public.orders(created_at desc);
create index if not exists idx_orders_fulfillment on public.orders(fulfillment_at);
create index if not exists idx_payments_order on public.payments(order_id);
create index if not exists idx_items_order on public.order_items(order_id);
create index if not exists idx_expenses_date on public.expenses(expense_date);
